// Primero verificamos la estructura del input
const inputData = $input.first().json;

// El JSON puede venir directamente como objeto o como array
let responseData;
if (Array.isArray(inputData)) {
  responseData = inputData[0];
} else {
  responseData = inputData;
}

const slotMap = responseData.slotMap;
const advisorList = responseData.advisorResponseList;

// Crear un mapa de advisorId -> advisorName para búsqueda rápida
// Eliminamos duplicados (mismo asesor puede aparecer con diferentes advisorType)
const advisorMap = {};
advisorList.forEach(advisor => {
  if (!advisorMap[advisor.advisorId]) {
    advisorMap[advisor.advisorId] = advisor.advisorName;
  }
});

const availableSlots = [];

// El slotMap contiene objetos cuyas claves son las horas (ej: "08:00")
for (const hourKey in slotMap) {
    // Aseguramos que la clave exista y no sea la clave de inicio/fin de día (" ")
    if (slotMap.hasOwnProperty(hourKey) && hourKey !== " ") {
        const dailySlots = slotMap[hourKey];

        // Iterar sobre los estados diarios (scheduleY) para esa hora
        for (const slot of dailySlots) {
            const libre = slot.livre;
            const passante = slot.passante;
            const ocupado = slot.ocupado || 0; // 🚨 NUEVO: Campo ocupado
            const naoTrabalha = slot.naoTrabalha;
            const fullDateTime = slot.scheduleY;

            // 🚨 REGLA DE ORO: Un turno está DISPONIBLE si:
            // 1. NO hay citas confirmadas (ocupado === 0)
            // 2. HAY capacidad operativa (passante + livre > 0)
            // 3. El personal está trabajando (naoTrabalha === 0)

            const capacidadDisponible = passante + libre;

            if (ocupado === 0 && capacidadDisponible > 0 && naoTrabalha === 0) {

                // Formateamos la fecha y hora
                const [date, time] = fullDateTime.split(' '); 

                // Agregar un slot por cada asesor disponible
                for (const advisorId in advisorMap) {
                  availableSlots.push({
                      json: {
                          Fecha: date,
                          Hora: time,
                          advisorId: parseInt(advisorId),
                          advisorName: advisorMap[advisorId],
                          Slots_Libres: libre, 
                          Slots_Pasante: passante,
                          Slots_Ocupados: ocupado, // 🚨 Incluimos para debug
                          Capacidad_Total_Disponible: capacidadDisponible
                      },
                  });
                }
            }
        }
    }
}

return availableSlots;

const hoy = new Date();
hoy.setHours(0, 0, 0, 0); // Resetear horas para comparar solo fechas

const slotsConDisponibilidadFormal = [];

// Recorrer los items del nodo anterior
for (const item of items) {
    const data = item.json;
    const slotsLibres = data.Slots_Libres;
    const slotsPasante = data.Slots_Pasante || 0;
    const slotsOcupados = data.Slots_Ocupados || 0;
    const capacidadTotal = data.Capacidad_Total_Disponible || 0;
    const fecha = data.Fecha;
    const hora = data.Hora;
    const advisorId = data.advisorId;
    const advisorName = data.advisorName;

    // Crear objeto Date de la fecha del turno
    const fechaTurno = new Date(fecha);
    fechaTurno.setHours(0, 0, 0, 0);

    // 🚨 Filtro con Regla de Oro:
    // 1. NO hay citas ocupadas (slotsOcupados === 0)
    // 2. HAY capacidad disponible (capacidadTotal > 0)
    // 3. La fecha es futura (mayor a hoy)
    if (slotsOcupados === 0 && capacidadTotal > 0 && fechaTurno > hoy) {
        slotsConDisponibilidadFormal.push({
            json: {
                Fecha: fecha,
                Hora: hora,
                advisorId: advisorId,
                advisorName: advisorName,
                Slots_Libres: slotsLibres,
                Slots_Pasante: slotsPasante,
                Slots_Ocupados: slotsOcupados,
                Capacidad_Total_Disponible: capacidadTotal
            }
        });
    }
}

// ORDENAR POR FECHA Y HORA
slotsConDisponibilidadFormal.sort((a, b) => {
    const fechaA = new Date(`${a.json.Fecha}T${a.json.Hora}`);
    const fechaB = new Date(`${b.json.Fecha}T${b.json.Hora}`);
    return fechaA - fechaB;
});

// AGRUPAR POR FECHA Y TURNO (Mañana/Tarde)
const slotsPorFechaYTurno = {};

slotsConDisponibilidadFormal.forEach(slot => {
    const fecha = slot.json.Fecha;
    const hora = slot.json.Hora;

    // Extraer la hora como número (ej: "07:40" -> 7.66, "14:30" -> 14.5)
    const [hh, mm] = hora.split(':').map(Number);
    const horaDecimal = hh + mm / 60;

    // Determinar si es Mañana (antes de 13:00) o Tarde (13:00 en adelante)
    const turno = horaDecimal < 13 ? 'mañana' : 'tarde';

    // Crear estructura de agrupación
    if (!slotsPorFechaYTurno[fecha]) {
        slotsPorFechaYTurno[fecha] = {
            mañana: [],
            tarde: []
        };
    }

    slotsPorFechaYTurno[fecha][turno].push(slot);
});

// SELECCIONAR 1 TURNO DE MAÑANA Y 1 DE TARDE POR DÍA (RANDOM)
const slotsSeleccionados = [];

for (const fecha in slotsPorFechaYTurno) {
    const turnos = slotsPorFechaYTurno[fecha];

    // 🌅 MAÑANA: Seleccionar 1 turno random
    if (turnos.mañana.length > 0) {
        const shuffledMañana = turnos.mañana.sort(() => Math.random() - 0.5);
        slotsSeleccionados.push(shuffledMañana[0]);
    }

    // 🌆 TARDE: Seleccionar 1 turno random
    if (turnos.tarde.length > 0) {
        const shuffledTarde = turnos.tarde.sort(() => Math.random() - 0.5);
        slotsSeleccionados.push(shuffledTarde[0]);
    }
}

// ORDENAR RESULTADO FINAL POR FECHA Y HORA
